import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { commandLogic } from 'lib/components/Command/commandLogic'
import { SearchItem } from 'lib/components/Search/searchLogic'
import { addProjectIdIfMissing } from 'lib/utils/kea-router'
import { PLACEHOLDER_HREF } from 'lib/utils/navigateToHref'
import { hasDangerousScheme, isExternalLink } from 'lib/utils/url'

import { osWindowsLogic } from '../windows/osWindowsLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface osSpotlightLogicValues {
    isCommandOpen: boolean // commandLogic
    isSpotlightOpen: boolean
    shownForWindow: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface osSpotlightLogicActions {
    closeCommand: () => {
        value: true
    } // commandLogic
    openCommand: (source: import('lib/components/Command/commandLogic').CommandOpenSource) => {
        source: import('lib/components/Command/commandLogic').CommandOpenSource
    } // commandLogic
    openWindow: (
        path: string,
        options?: import('../windows/osWindowsLogic').OsOpenWindowOptions | undefined
    ) => {
        id: string
        options: import('../windows/osWindowsLogic').OsOpenWindowOptions
        path: string
    } // osWindowsLogic
    closeSpotlight: () => {
        value: true
    }
    openSpotlight: () => {
        value: true
    }
    selectResult: (
        item: SearchItem,
        newWindow: boolean
    ) => {
        item: SearchItem
        newWindow: boolean
    }
    showSpotlight: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface osSpotlightLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isSpotlightOpen: (isCommandOpen: boolean, shownForWindow: any) => boolean
    }
}

export type osSpotlightLogicType = MakeLogicType<
    osSpotlightLogicValues,
    osSpotlightLogicActions,
    Record<string, any>,
    osSpotlightLogicMeta
>

/**
 * The OS spotlight is the app's command menu (`commandLogic`) with results that open in windows. Cmd+K on
 * the desktop or inside a window opens it, and a menu bar can call `openSpotlight`.
 */
export const osSpotlightLogic = kea<osSpotlightLogicType>([
    path(['scenes', 'os', 'spotlight', 'osSpotlightLogic']),
    connect(() => ({
        values: [commandLogic, ['isCommandOpen']],
        actions: [commandLogic, ['openCommand', 'closeCommand'], osWindowsLogic, ['openWindow']],
    })),
    actions({
        /** Opens the spotlight for a request that the framed app already counted as a command menu open. */
        showSpotlight: true,
        openSpotlight: true,
        closeSpotlight: true,
        selectResult: (item: SearchItem, newWindow: boolean) => ({ item, newWindow }),
    }),
    reducers({
        shownForWindow: [
            false,
            {
                showSpotlight: () => true,
                closeSpotlight: () => false,
                closeCommand: () => false,
            },
        ],
    }),
    selectors({
        isSpotlightOpen: [
            (s) => [s.isCommandOpen, s.shownForWindow],
            (isCommandOpen: boolean, shownForWindow: boolean): boolean => isCommandOpen || shownForWindow,
        ],
    }),
    listeners(({ actions }) => ({
        openSpotlight: () => actions.openCommand('nav-search-button'),
        closeSpotlight: () => actions.closeCommand(),
        selectResult: ({ item, newWindow }) => {
            actions.closeCommand()
            if (item.onSelect) {
                item.onSelect()
                return
            }
            const href = item.href
            // A result's href can come from team-writable data, so a script URL must go nowhere.
            if (!href || href === PLACEHOLDER_HREF || hasDangerousScheme(href)) {
                return
            }
            if (isExternalLink(href)) {
                window.open(href, '_blank', 'noopener,noreferrer')
                return
            }
            actions.openWindow(addProjectIdIfMissing(href), { newWindow })
        },
    })),
])
